const e="Monto fijo",a="Lista reordenable de cuentas bancarias",o="Porcentaje",n="Remanente",t="{{name}} ({{account_number}})",r="Dividir por",i='Puedes dividir tu cheque de pago en diferentes cuentas por porcentaje o por montos fijos en dólares. Al dividir por monto, puedes reordenar la prioridad de las cuentas bancarias haciendo clic y arrastrando el ícono de lista a la izquierda del campo de cuenta bancaria. Pagaremos los montos en el orden especificado hasta que tu salario haya sido distribuido por completo a la última cuenta de "remanente".',s={amountError:"Ingresa un monto válido",percentageAmountError:"El porcentaje debe ser un número entero entre 0 y 100",percentageErrorWithTotal:"Las divisiones deben sumar el 100 %. Actualmente {{total}} %."},d={amountLabel:e,draggableListLabel:a,percentageLabel:o,remainderLabel:n,splitAmountLabel:t,splitByLabel:r,splitDescription:i,validations:s};export{e as amountLabel,d as default,a as draggableListLabel,o as percentageLabel,n as remainderLabel,t as splitAmountLabel,r as splitByLabel,i as splitDescription,s as validations};
